      "value": "20.00",
      "units": "kPa",
      "narrative_section": "4.8"
    },
    {
      "name": "pt_fault_below",
      "value": "-5.00",
      "units": "kPa",
      "narrative_section": "4.8"
    },
    {
      "name": "cycle_time_budget",
      "value": "23.0",
      "units": "s",
      "narrative_section": "4.8"
    }
  ],
  "steps": [
    {
      "name": "Start / Idle",
      "entry": "Station idle and previous pallet departs",
      "exit": "Pallet in position (ZS-2008 rising edge) with cell in auto mode and no ST20 fault active"
    },
    {
      "name": "Clamp",
      "entry": "Cycle start triggered; clamp solenoid XY-2002 energized",
      "exit": "Clamp confirmed closed (ZS-2002A made and ZS-2002B clear)"
    },
    {
      "name": "Fill",
      "entry": "Clamp confirmed closed; fill valve XV-2003 opens",
      "exit": "Pressure reaches 14.50 kPa (or fill timeout of 8.0 s elapses)"
    },
    {
      "name": "Stabilise",
      "entry": "Fill valve closes when 14.50 kPa reached",
      "exit": "Stabilisation timer completes and baseline pressure is recorded"
    },
    {
      "name": "Test",
      "entry": "Stabilisation complete; pack remains isolated",
      "exit": "10.0 s test window elapses; final pressure recorded and decay calculated"
    },
    {
      "name": "Decision",
      "entry": "Test window completes",
      "exit": "Result evaluated as PASS (decay <= 0.30 kPa) or FAIL (decay > 0.30 kPa)"
    },
    {
      "name": "Vent",
      "entry": "Test evaluation complete (or cycle abort from fault/E-stop)",
      "exit": "Vent timer completes and pressure drops below 1.00 kPa with PT-2001 healthy"
    },
    {
      "name": "Unclamp",
      "entry": "Vent conditions satisfied; clamp solenoid de-energized",
      "exit": "Clamp confirmed open (ZS-2002B made and ZS-2002A clear)"
    },
    {
      "name": "Done",
      "entry": "Clamp confirmed open",
      "exit": "Pallet departs test position (ZS-2008 clears)"
    }
  ],
  "interlocks": [
    {
      "cause": "Cell not in auto mode, ST20 fault active, or station busy",
      "effect": "Inhibits cycle start on pallet arrival"
    },
    {
      "cause": "Pallet sensor drops and returns while test is running",
      "effect": "Sequence restart is inhibited"
    },
    {
      "cause": "Clamp closed confirmation lost while filling",
      "effect": "Fill valve XV-2003 closes immediately"
    },
    {
      "cause": "Pack pressure not below 1.00 kPa or PT-2001 signal fault active",
      "effect": "Unclamp is inhibited; station holds in VENT with vent valve held open"
    },
    {
      "cause": "Over-pressure detected (> 20.00 kPa)",
      "effect": "Fill valve closes immediately, vent valve is held open, and FAIL is latched"
    },
    {
      "cause": "E-stop chain lost during cycle",
      "effect": "Cycle aborts immediately to VENT with FAIL result"
    },
    {
      "cause": "Station not at step DONE",
      "effect": "PASS (RS-2006) and FAIL (RS-2007) signals to line controller are suppressed"
    }
  ],
  "alarms": [
    {
      "name": "Fill timeout",
      "condition": "Test pressure (14.50 kPa) not reached within 8.0 s while in FILL step",
      "action": "Abort sequence to VENT, set FAIL result, and illuminate ST20 fault beacon HL-2011"
    },
    {
      "name": "Over-pressure",
      "condition": "PT-2001 pack pressure exceeds 20.00 kPa (latched)",
      "action": "Close fill valve, hold vent valve open, latch FAIL, and illuminate ST20 fault beacon HL-2011"
    },
    {
      "name": "PT-2001 signal fault",
      "condition": "PT-2001 reading drops below -5.00 kPa (indicating wire break)",
      "action": "Inhibit cycle start, hold unclamp in VENT, and illuminate ST20 fault beacon HL-2011"
    },
    {
      "name": "Supply air low",
      "condition": "PS-2009 supply air pressure lost while ST20 is busy (latched)",
      "action": "Abort sequence to VENT, set FAIL result, and illuminate ST20 fault beacon HL-2011"
    }
  ],
  "conflicts": [
    {
      "item": "stabilise_time",
      "narrative_says": "3 s (Section 4.4)",
      "parameter_sheet_says": "5.0 s (T22, updated via MOC-2021-044)",
      "program_says": "5.0 s (R13: OUT T22 K50 on 100 ms base)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "test_pressure",
      "narrative_says": "15.2 kPa regulator setpoint (Section 4.3)",
      "parameter_sheet_says": "15.00 kPa(g) test pressure (note: supply regulator set to 15.2 kPa)",
      "program_says": "Not programmed in PLC (mechanical regulator PR-2012)",
      "authoritative": "parameter sheet"
    },
    {
      "item": "vent_time",
      "narrative_says": "0.5 s (Section 4.7)",
      "parameter_sheet_says": "0.5 s (T24)",
      "program_says": "5.0 s (R21: OUT T200 K50; on FX5 T200 uses 100 ms base = 5.0 s due to FX3 migration discrepancy)",
      "authoritative": "parameter sheet"
    }
  ]
}
